require __DIR__.'/../includes/config.php';require __DIR__.'/../includes/functions.php';$u=require_role(['operator']);
$st=$pdo->query('SELECT c.name,c.slug,COUNT(r.id) total FROM categories c LEFT JOIN requests r ON r.category_id=c.id GROUP BY c.id ORDER BY total DESC');$rows=$st->fetchAll();$st=$pdo->query("SELECT AVG(TIMESTAMPDIFF(MINUTE,r.created_at,h.created_at)) FROM requests r JOIN request_status_history h ON h.request_id=r.id AND h.status=1");$avg=$st->fetchColumn();$avgText=$avg===null?'—':round((float)$avg).' min';$st=$pdo->query('SELECT c.name,COUNT(*) total FROM requests r JOIN categories c ON c.id=r.category_id GROUP BY c.id ORDER BY total DESC LIMIT 1');$common=$st->fetch();$max=max(1,max(array_column($rows,'total')?:[1]));$pageTitle='Analytics';require __DIR__.'/../includes/header.php';?>
<div class="eyebrow">DATA-DRIVEN TOWNSHIP SAFETY</div><h2>Operational <span class="red">Analytics</span></h2><p class="subtext">Simple demo analytics to help the centre identify recurring issues and monitor response efficiency.</p><div class="grid grid-3"><div class="dark-panel"><div class="eyebrow">AVG. TIME TO ASSIGN</div><div class="stat"><?=e($avgText)?></div><div class="stat-label">Created to first assignment (available records)</div></div><div class="dark-panel"><div class="eyebrow">MOST COMMON ISSUE</div><div class="stat" style="font-size:20px"><?=e($common['name']??'No data')?></div><div class="stat-label"><?= (int)($common['total']??0)?> recorded requests</div></div><div class="dark-panel"><div class="eyebrow">CATEGORIES</div><div class="stat"><?=count($rows)?></div><div class="stat-label">Issue types available</div></div></div><div class="card" style="margin-top:16px"><h3>Requests by category</h3><?php foreach($rows as $r):$color=['fire-safety'=>'#E53935','plumbing'=>'#2F7DE1','electrical'=>'#F5A623','security'=>'#2E9E5B','maintenance'=>'#3F6FB5','other'=>'#6B7280'][$r['slug']]??'#0F2340';?><div style="margin:17px 0"><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:6px"><span><?=e($r['name'])?></span><strong><?=$r['total']?></strong></div><div style="height:12px;background:#f1efec;border-radius:20px;overflow:hidden"><div style="height:100%;width:<?=round($r['total']/$max*100)?>%;background:<?=$color?>"></div></div></div><?php endforeach;?></div><p class="muted" style="font-size:11px">Response-time analytics are based on recorded assignment history; seeded demo data may not represent operational performance.</p><?php require __DIR__.'/../includes/footer.php';?>
